 let state=Arc::new(Mutex::new(QueryState::default()));let mut attempt=QueryAttempt::new(state.clone(),true);let request=crate::policy_request::WorkspacePolicyRequest{root:root.clone(),recursive_roots:workspace.recursive_roots().to_vec(),configuration:configuration.clone()};attempt.capture_with_workspace_recorded_sources(&front,queries.clone(),workspace.clone(),&request,&inputs).unwrap();let(_,admission)=crate::request_runner::runner_freshness::admit_workspace_captured(&inputs,None,&crate::frozen_inputs::Inputs::Live,&Default::default(),workspace.clone()).unwrap();attempt.admit_workspace_policy(admission).unwrap();attempt.finish_analyzed();let snapshot=state.lock().unwrap().snapshot.take().unwrap();let scope=Arc::new(snapshot.workspace_native_read().unwrap().query_receipt(&mut |_|Ok(())).unwrap());
 let intent=PolicyInputRequest{workspace:None,files:vec![PolicyInputFile{path:configuration,role:PolicyInputRole::Configuration,required:false}],search_folders:vec![]}.admit().unwrap();let capture=Arc::new(crate::runner_host::policy_capture::capture(&front,&inputs,&intent.capture_files(),&[]).unwrap().bind_request(&intent).unwrap());Self{root,queries,workspace,scope,capture,reads,_front:front,_snapshot:snapshot}
