 fn params(&self,request:Request)->Params{let root=self.workspace.root().to_owned();let configuration_path=self.workspace.configuration().0.to_owned();let configuration=Key::new(RAW_CONFIG,finite::metadata_key(&(&root,&configuration_path)).unwrap().id);let mut p=Params{key:Key::new(finite::REACTIVE_RESULT,0),issuance:self.workspace.issuance(),evidence:self.capture.semantic_source_evidence().key(),locator:finite::source_locator(&self.capture).unwrap(),configuration,configuration_path,root,request};p.key=key_for(&p,&p.request).unwrap();p}
