#[test]fn full_original_query_uses_130_actual_files_and_only_demanded_body_without_reread(){let f=Fixture::new();let before=f.reads.load(Ordering::Relaxed);let pointer=f.get(Fixture::read("leaf"),|value|{let Value::RawReads(value)=value else{panic!("actual full read role")};assert_eq!(value.facts().reads().len(),1);assert_eq!(value.facts().reads()[0].var,"charge");Ok(value.facts().reads().as_ptr()as usize)}).unwrap();assert_eq!(f.queries.db.stats(super::super::super::body_syntax::BODY_SYNTAX).computed,1);assert_eq!(f.queries.db.stats(finite::REACTIVE_RESULT).computed,1,"no unrelated Globals/body demand");assert_eq!(f.reads.load(Ordering::Relaxed),before);f.get(Fixture::read("leaf"),|value|{let Value::RawReads(value)=value else{panic!("full role")};assert_eq!(value.facts().reads().as_ptr()as usize,pointer);Ok(())}).unwrap();assert_eq!(f.reads.load(Ordering::Relaxed),before);assert!(f.queries.raw_policy.admission.workspace_operation.lock().unwrap().is_none());}
#[test]fn current_operation_rebinds_after_budget_drop_for_evicted_child_and_verify_green(){let f=Fixture::new();let mut old_budget=Weak::<Budget>::new();let root=f.params(Request::Dependencies).key;f.get(Request::Dependencies,|value|{assert!(matches!(value,Value::RawDependencies(_)));let loan=f.queries.raw_policy.admission.current_workspace_operation(f.workspace.issuance(),f.capture.semantic_source_evidence().key())?;old_budget=Arc::downgrade(&loan.budget);Ok(())}).unwrap();assert!(old_budget.upgrade().is_none(),"finished operation cannot be kept alive by cached Params");assert!(f.queries.raw_policy.admission.workspace_operation.lock().unwrap().is_none());
 let child=f.params(Fixture::read("draw")).key;assert!(f.queries.db.value_bytes_at(child)>0);assert!(f.queries.db.evict_value_at(child)>0);let unrelated=Key::new(Kind(804),1);f.queries.db.define_input(unrelated.kind,"full-operation-revision");f.queries.db.set_input(unrelated,1usize,1);f.queries.db.set_verify(true);let before=f.reads.load(Ordering::Relaxed);let computed=f.queries.db.stats(finite::REACTIVE_RESULT).computed;f.get(Request::Dependencies,|value|{assert!(matches!(value,Value::RawDependencies(_)));Ok(())}).unwrap();assert!(f.queries.db.stats(finite::REACTIVE_RESULT).computed>computed,"evicted actual child recomputes under current root control");assert!(f.queries.db.verify_failures().is_empty());assert!(f.queries.db.dependants(&[child]).contains(&root));assert_eq!(f.reads.load(Ordering::Relaxed),before);assert!(old_budget.upgrade().is_none());assert!(f.queries.raw_policy.admission.workspace_operation.lock().unwrap().is_none());}
#[test]fn full_original_query_actual_io_cancel_and_callback_unwind_leave_no_operation_control(){let f=Fixture::new();let failure=f.queries.fail_body_syntax_after_for_test(0,io::Error::from_raw_os_error(1450));let error=f.get(Fixture::read("leaf"),|_|->io::Result<()>{panic!("actual IO cannot deliver")}).unwrap_err();assert_eq!(error.raw_os_error(),Some(1450));assert_eq!(f.queries.db.stats(finite::REACTIVE_RESULT).computed,0);assert!(f.queries.raw_policy.admission.workspace_operation.lock().unwrap().is_none());drop(failure);
 f.get(Fixture::read("leaf"),|_|Ok(())).unwrap();let token=crate::daemon::control::Cancellation::default();let binding=crate::daemon::control::bind_with_deadline(token.clone(),Instant::now()+Duration::from_secs(30));token.cancel();assert_eq!(f.get(Fixture::read("leaf"),|_|->io::Result<()>{panic!("cancel cannot deliver")}).unwrap_err().kind(),io::ErrorKind::Interrupted);drop(binding);
 let panic=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||f.get(Fixture::read("leaf"),|_|->io::Result<()>{panic!("actual consumer unwind")})));assert!(panic.is_err());assert!(f.queries.raw_policy.admission.workspace_operation.lock().unwrap_or_else(|e|e.into_inner()).is_none());f.get(Fixture::read("leaf"),|_|Ok(())).unwrap();}

#[test]fn full_original_quota_refuses_constructor_and_operation_weak_preflight_then_recovers(){let f=Fixture::new();let before=(Arc::weak_count(&f.scope),Arc::weak_count(&f.workspace),Arc::weak_count(&f.capture));let fixed=std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>();for limit in [1,fixed]{let error=f.queries.with_workspace_reactive_limit(&f.workspace,&f.scope,&f.capture,Fixture::read("leaf"),Some(limit),|_|->io::Result<()>{panic!("quota cannot deliver full source result")}).unwrap_err();assert_eq!(error.kind(),io::ErrorKind::OutOfMemory);assert_eq!(f.queries.db.stats(finite::REACTIVE_RESULT).computed,0);assert_eq!(f.queries.db.stats(super::super::super::body_syntax::BODY_SYNTAX).computed,0);assert!(f.queries.raw_policy.admission.workspace_operation.lock().unwrap().is_none());assert_eq!((Arc::weak_count(&f.scope),Arc::weak_count(&f.workspace),Arc::weak_count(&f.capture)),before,"pre-admission refusal cannot retain operation weak owners");}f.get(Fixture::read("leaf"),|_|Ok(())).unwrap();}
